(()=>{const q=s=>document.querySelector(s);async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined}),d=await r.json();if(r.status===401)location.replace('/login');if(!r.ok)throw Error(d.message||'Request failed.');return d;}async function load(){const {user}=await api('/api/auth/me');q('#password-section').hidden=!user.requires_password_change;q('#mfa-section').hidden=user.requires_password_change||!user.requires_mfa;q('#continue-dashboard').hidden=user.requires_password_change||user.requires_mfa;q('#security-state').textContent=user.requires_password_change?'Change your password before accessing your workspace.':user.requires_mfa?'Complete multifactor authentication to continue.':'Your account is ready.';if(user.requires_mfa&&!user.requires_password_change&&!user.mfa_enabled){const d=await api('/api/auth/mfa/setup',{});q('#mfa-title').textContent='Set up your authenticator';q('#mfa-setup').hidden=false;q('#mfa-secret').textContent=d.secret;q('#mfa-uri').href=d.uri;}}async function run(form,action){q('#security-error').hidden=true;const b=form.querySelector('button');b.disabled=true;try{await action();form.reset();await load();}catch(x){q('#security-error').textContent=x.message;q('#security-error').hidden=false;}finally{b.disabled=false;}}q('#password-form').onsubmit=ev=>{ev.preventDefault();run(ev.target,async()=>{const d=Object.fromEntries(new FormData(ev.target));if(d.new_password!==d.confirm_password)throw Error('New passwords do not match.');await api('/api/auth/password',d);});};q('#mfa-form').onsubmit=ev=>{ev.preventDefault();run(ev.target,()=>api('/api/auth/mfa/verify',Object.fromEntries(new FormData(ev.target))));};q('#security-logout').onclick=async()=>{await api('/api/auth/logout',{});location.replace('/login');};q('#continue-dashboard').onclick=()=>location.replace('/dashboard');load().catch(x=>{q('#security-error').textContent=x.message;q('#security-error').hidden=false;});})();
